//! Mega CD scan on discs generated by `tests/tools/mkcd.py` (original data, no commercial content, no network).
//! Design `docs/design/v2.1-megacd-express.md` §5. Needs `python3`.

use std::collections::BTreeSet;
use std::fs;
use std::path::Path;
use std::process::Command;
use std::sync::atomic::AtomicBool;

use emu_library::{DiscFormat, DiscRegion, Library, ScanOptions, ScanReport, disc_info};

fn mkcd(args: &[&str]) {
    let script = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/tools/mkcd.py");
    let out = Command::new("python3")
        .arg("-I")
        .arg(script)
        .args(args)
        .output()
        .expect("python3 is required for the Mega CD fixtures");
    assert!(
        out.status.success(),
        "mkcd.py {args:?}: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}

fn scan(lib: &mut Library, root: &Path) -> ScanReport {
    let opts = ScanOptions {
        roots: vec![root.to_path_buf()],
        ..Default::default()
    };
    lib.scan(&opts, &AtomicBool::new(false), &mut |_| {})
        .unwrap()
}

/// `(system, path relative to root)` of every listed game, sorted.
fn listed(lib: &Library, root: &Path) -> BTreeSet<(String, String)> {
    lib.games()
        .unwrap()
        .into_iter()
        .map(|g| {
            let rel = g.path.strip_prefix(root).unwrap().to_string_lossy();
            (g.system, rel.replace('\\', "/"))
        })
        .collect()
}

fn pair(system: &str, path: &str) -> (String, String) {
    (system.to_owned(), path.to_owned())
}

fn cartridge() -> Vec<u8> {
    let mut rom = vec![0u8; 0x4000];
    rom[0x100..0x110].copy_from_slice(b"SEGA MEGA DRIVE ");
    rom
}

fn region_of(path: &Path) -> Option<DiscRegion> {
    let info = disc_info(path).unwrap().expect("a Sega CD header");
    assert_eq!(info.format, DiscFormat::SegaCd);
    info.region
}

/// Every region, both layouts, 2048 and 2352 data tracks: one `megacd` game per disc, no track listed.
#[test]
fn generated_discs_are_classified_by_their_cue() {
    let tmp = tempfile::tempdir().unwrap();
    let root = tmp.path().join("roms");
    let r = |s: &str| root.join(s).to_string_lossy().into_owned();
    mkcd(&[
        "megacd",
        &r("megacd/E"),
        "--name",
        "Dune (Europe)",
        "--region",
        "E",
        "--audio-tracks",
        "2",
        "--iso",
    ]);
    mkcd(&[
        "megacd",
        &r("megacd/J"),
        "--name",
        "Mono Japan",
        "--region",
        "J",
        "--layout",
        "mono",
        "--audio-tracks",
        "2",
    ]);
    mkcd(&[
        "megacd",
        &r("megacd/U"),
        "--name",
        "Plain Usa",
        "--region",
        "U",
        "--sector",
        "2048",
    ]);
    // Outside any `megacd/` folder: classified by the `SEGADISCSYSTEM` header alone.
    mkcd(&[
        "megacd",
        &r("elsewhere/Euro Disc"),
        "--name",
        "Euro Disc",
        "--region",
        "E",
    ]);

    let mut lib = Library::open_in_memory().unwrap();
    let report = scan(&mut lib, &root);
    assert!(report.errors.is_empty(), "{report:?}");
    // The `.iso` next to `Dune (Europe).cue` is not referenced by the cue: it stays a game of its own (the
    // user's copy of the data track); the three tracks are hidden.
    assert_eq!(
        listed(&lib, &root),
        BTreeSet::from([
            pair("megacd", "megacd/E/Dune (Europe).cue"),
            pair("megacd", "megacd/E/Dune (Europe).iso"),
            pair("megacd", "megacd/J/Mono Japan.cue"),
            pair("megacd", "megacd/U/Plain Usa.cue"),
            pair("megacd", "elsewhere/Euro Disc/Euro Disc.cue"),
        ])
    );
    for g in lib.games().unwrap() {
        assert_eq!((g.sha1, g.crc32), (None, None), "{:?} was hashed", g.path);
        assert!(g.media.is_empty());
    }

    let again = scan(&mut lib, &root);
    assert_eq!((again.added, again.removed, again.unchanged), (0, 0, 5));
}

/// The probe reads byte 0x20B of the data track, through the `.cue`, the raw track or the `.iso`.
#[test]
fn region_comes_from_the_header() {
    let tmp = tempfile::tempdir().unwrap();
    let dir = tmp.path();
    for (code, region) in [
        ("E", DiscRegion::Europe),
        ("J", DiscRegion::Japan),
        ("U", DiscRegion::Usa),
    ] {
        let out = dir.join(code);
        mkcd(&[
            "megacd",
            out.to_str().unwrap(),
            "--name",
            "Disc",
            "--region",
            code,
            "--iso",
        ]);
        assert_eq!(region_of(&out.join("Disc.cue")), Some(region), "cue {code}");
        assert_eq!(region_of(&out.join("Disc.iso")), Some(region), "iso {code}");
        assert_eq!(
            region_of(&out.join("Disc (Track 1).bin")),
            Some(region),
            "bin {code}"
        );
        let mono = dir.join(format!("mono{code}"));
        mkcd(&[
            "megacd",
            mono.to_str().unwrap(),
            "--name",
            "Disc",
            "--region",
            code,
            "--layout",
            "mono",
        ]);
        assert_eq!(
            region_of(&mono.join("Disc.cue")),
            Some(region),
            "mono {code}"
        );
    }
}

/// The 240p layout: data `.iso` + two `WAVE` tracks. Built from generated files, with a hand-written cue.
#[test]
fn wave_tracks_are_hidden() {
    let tmp = tempfile::tempdir().unwrap();
    let root = tmp.path().join("roms");
    let work = tmp.path().join("gen");
    mkcd(&[
        "megacd",
        work.to_str().unwrap(),
        "--name",
        "Wave Disc",
        "--region",
        "U",
        "--audio-tracks",
        "2",
        "--iso",
    ]);
    let dir = root.join("wave");
    fs::create_dir_all(&dir).unwrap();
    fs::copy(work.join("Wave Disc.iso"), dir.join("data.iso")).unwrap();
    for (n, from) in [
        (2, "Wave Disc (Track 2).bin"),
        (3, "Wave Disc (Track 3).bin"),
    ] {
        fs::copy(work.join(from), dir.join(format!("audio-{n}.wav"))).unwrap();
    }
    fs::write(
        dir.join("Wave.cue"),
        "FILE \"data.iso\" BINARY\r\n  TRACK 01 MODE1/2048\r\n    INDEX 01 00:00:00\r\n\
         FILE \"audio-2.wav\" WAVE\r\n  TRACK 02 AUDIO\r\n    INDEX 01 00:00:00\r\n\
         FILE \"audio-3.wav\" WAVE\r\n  TRACK 03 AUDIO\r\n    INDEX 01 00:00:00\r\n",
    )
    .unwrap();
    let mut lib = Library::open_in_memory().unwrap();
    let report = scan(&mut lib, &root);
    assert!(report.errors.is_empty(), "{report:?}");
    assert_eq!(
        listed(&lib, &root),
        BTreeSet::from([pair("megacd", "wave/Wave.cue")])
    );
    assert_eq!(region_of(&dir.join("Wave.cue")), Some(DiscRegion::Usa));
}

/// A lone Sega CD data track without a cue is not a Mega Drive game; cartridges are untouched (1.0 behaviour).
#[test]
fn orphan_track_is_ignored_and_cartridges_still_hashed() {
    let tmp = tempfile::tempdir().unwrap();
    let root = tmp.path().join("roms");
    fs::create_dir_all(root.join("md")).unwrap();
    mkcd(&["orphan", root.join("Lost Track 01.bin").to_str().unwrap()]);
    fs::write(root.join("md/Sonic.bin"), cartridge()).unwrap();
    fs::write(root.join("md/Other.md"), cartridge()).unwrap();

    let mut lib = Library::open_in_memory().unwrap();
    let report = scan(&mut lib, &root);
    assert!(
        report
            .errors
            .iter()
            .any(|(p, m)| p.ends_with("Lost Track 01.bin") && m.contains("sans fichier .cue")),
        "{report:?}"
    );
    assert_eq!(
        listed(&lib, &root),
        BTreeSet::from([
            pair("megadrive", "md/Sonic.bin"),
            pair("megadrive", "md/Other.md")
        ])
    );
    assert!(lib.games().unwrap().iter().all(|g| g.sha1.is_some()));
}

/// Stores `entries` (name, source file) in a zip, with the interpreter in isolated mode.
fn zip_files(out: &Path, entries: &[(&str, &Path)]) {
    let code = "import sys, zipfile\n\
        z = zipfile.ZipFile(sys.argv[1], 'w')\n\
        for i in range(2, len(sys.argv), 2):\n\
        \x20   z.write(sys.argv[i + 1], sys.argv[i])\n\
        z.close()\n";
    let mut cmd = Command::new("python3");
    cmd.args(["-I", "-c", code]).arg(out);
    for (name, path) in entries {
        cmd.arg(name).arg(path);
    }
    assert!(cmd.status().expect("python3").success());
}

/// A zipped Sega CD track is ignored with the same message as a loose one; zipped cartridges are still listed.
#[test]
fn zipped_orphan_track_is_ignored_and_zipped_cartridges_are_kept() {
    let tmp = tempfile::tempdir().unwrap();
    let work = tmp.path().join("work");
    let root = tmp.path().join("roms");
    fs::create_dir_all(&work).unwrap();
    fs::create_dir_all(&root).unwrap();
    let track = work.join("Lost Track 01.bin");
    mkcd(&["orphan", track.to_str().unwrap()]);
    zip_files(&root.join("Lost.zip"), &[("Lost Track 01.bin", &track)]);
    let md = work.join("Sonic.bin");
    fs::write(&md, cartridge()).unwrap();
    zip_files(&root.join("Sonic.zip"), &[("Sonic.bin", &md)]);
    let x32 = work.join("Star.bin");
    let mut rom = cartridge();
    rom[0x100..0x108].copy_from_slice(b"SEGA 32X");
    fs::write(&x32, rom).unwrap();
    zip_files(&root.join("Star.zip"), &[("Star.bin", &x32)]);

    let mut lib = Library::open_in_memory().unwrap();
    let report = scan(&mut lib, &root);
    assert!(
        report
            .errors
            .iter()
            .any(|(p, m)| p.ends_with("Lost.zip") && m.contains("sans fichier .cue")),
        "{report:?}"
    );
    assert_eq!(
        listed(&lib, &root),
        BTreeSet::from([pair("megadrive", "Sonic.zip"), pair("32x", "Star.zip")])
    );
}
